            {
                var protocolRawValue = DownloadProtocolValueConverter.ToJsonValue(indexerResource.Protocol!.Value);
                writer.WriteString("protocol", protocolRawValue);
            }
            if (indexerResource.PriorityOption.IsSet)
                writer.WriteNumber("priority", indexerResource.PriorityOption.Value!.Value);

            if (indexerResource.SeasonSearchMaximumSingleEpisodeAgeOption.IsSet)
                writer.WriteNumber("seasonSearchMaximumSingleEpisodeAge", indexerResource.SeasonSearchMaximumSingleEpisodeAgeOption.Value!.Value);

            if (indexerResource.DownloadClientIdOption.IsSet)
                writer.WriteNumber("downloadClientId", indexerResource.DownloadClientIdOption.Value!.Value);
        }
    }
}
